(function(){
  'use strict';
  var canvas=document.getElementById('world'),seconds=0,focus='',paused=matchMedia('(prefers-reduced-motion: reduce)').matches,slow=false,loaded=false,failed=false,last=0,dirty=true,drawPopulation;
  function update(){document.getElementById('pause').textContent=paused?'Play':'Pause';document.getElementById('slow').setAttribute('aria-pressed',String(slow));document.getElementById('wide').setAttribute('aria-pressed',String(!focus));canvas.setAttribute('aria-label',focus==='ramen'?'Close-up of the ramen-shop visit':focus==='flowers'?'Close-up of a neighbor smelling flowers':'Painted neighbors walk, browse flowers, and visit the ramen shop');}
  function draw(){if(!loaded)return;drawPopulation(VisitWorld.population(seconds,8),focus);var text=paused?'Paused.':focus==='ramen'?'Ramen visit · follow her hand, the doorway, and the counter window.':focus==='flowers'?'Flower display · bend toward the blossoms, pause, and walk on.':'Eight neighbors · two shop visits and six passersby.';if(slow)text+=' Half speed.';if(document.getElementById('status').textContent!==text)document.getElementById('status').textContent=text;dirty=false;}
  function watch(t,view){seconds=t;focus=view;paused=matchMedia('(prefers-reduced-motion: reduce)').matches;last=0;dirty=true;update();}
  document.getElementById('ramen').onclick=function(){watch(VisitWorld.entranceTime,'ramen');};document.getElementById('flowers').onclick=function(){watch(VisitWorld.flowerTime,'flowers');};document.getElementById('wide').onclick=function(){focus='';dirty=true;update();};
  document.getElementById('pause').onclick=function(){paused=!paused;dirty=true;update();};document.getElementById('slow').onclick=function(){slow=!slow;dirty=true;update();};document.getElementById('restart').onclick=function(){seconds=0;dirty=true;last=0;};document.getElementById('fullscreen').onclick=function(){if(canvas.requestFullscreen)canvas.requestFullscreen().catch(function(){document.getElementById('status').textContent='Full screen is unavailable in this browser.';});};document.addEventListener('visibilitychange',function(){last=0;});
  function tick(now){var dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(!document.hidden){if(!paused)seconds+=dt*(slow?.5:1);if(!paused||dirty)draw();}requestAnimationFrame(tick);}
  window.VisitStudy={state:function(){return {loaded:loaded,failed:failed,seconds:seconds,focus:focus,paused:paused,slow:slow,residents:VisitWorld.population(seconds,8),entranceTime:VisitWorld.entranceTime,windowTime:VisitWorld.windowTime,flowerTime:VisitWorld.flowerTime};},inspect:function(t,view){seconds=t;if(view!==undefined)focus=view;paused=true;update();draw();}};
  var files={background:'../assets/street.png',sideUpper:'../assets/skin/resident-arms.png',sideLegs:'../assets/skin/resident-layered.png',props:'../assets/rig/resident.png',front:'../assets/directions/front.png',rear:'../assets/directions/rear.png',front45:'../assets/directions/front45.png',rear45:'../assets/directions/rear45.png',legs:'../assets/directions/legs.png',interior:'../assets/rig/interior.png'};
  Promise.all(Object.entries(files).map(function(entry){return new Promise(function(resolve,reject){var img=new Image();img.onload=function(){resolve([entry[0],img]);};img.onerror=reject;img.src=entry[1];});})).then(function(entries){drawPopulation=VisitRenderer.renderer(canvas,Object.fromEntries(entries));loaded=true;document.getElementById('loading').hidden=true;draw();}).catch(function(){failed=true;document.getElementById('loading').textContent='The artwork could not load. Please reload to try again.';});update();requestAnimationFrame(tick);
})();
